"""Данные для таблицы моделей: одна запись m() = одна модель (или семейство с общими весами).

Строка таблицы = модель × режим работы. Режимы различаются тем, что подаётся на вход (текст, картинка, видео, аудио, маска):
  split=[dict(id=…, mode='вход → выход', wf=[…], cap={…}, …), …] — каждый режим станет своей строкой; в режиме можно
  переопределить любое поле модели (cat, native, prompt, plus, minus, arch, time…), add=dict(поле='…') дописывает текст к полю модели.
  Первый режим (обычно из текста) держит id модели без суффикса, остальные — с суффиксом (-i2v, -edit, -control…).
  У модели с одним режимом mode и cap пишутся прямо в m().
  exp у модели с режимами — только внутри режима: опыт относится к тому режиму, которым работал.
cat — категория; по ней строка попадает на лист (SHEETS): Фото…/Редактирование фото → «Фото», Видео… → «Видео», Аудио… → «Аудио», Апскейл… → «Апскейл», остальное → «Утилиты и LLM».
  Апскейл — отдельный шаг после генерации, а не режим модели: даже апскейл на весах Z-Image или Illustrious — своя запись.
cap — умения режима для колонок листа: {ключ из SHEETS: '✓ …' | '—' | '?'}; нет ключа — «—» (не умеет в этом режиме).

arch — параметры для оценки (см. estimate.py):
  N  — параметров в диффузионной модели (млрд), d — ширина, L — число слоёв внимания,
  ffn — ширина самого широкого промежуточного тензора (для доли от предела активаций),
  px — пикселей на токен по стороне (VAE × patch), tf — сжатие по времени ('wan' 4n+1, 'ltx' 8n+1, 'mm' 17k+5),
  W,H,F — разрешение/кадры шаблона по умолчанию, steps — шаги шаблона, passes — проходов на шаг (CFG>1 → 2),
  mult — во сколько раз больше токенов из-за референсов/исходного видео, vae — сек на мегапиксель-кадр декода,
  native_F — родной предел кадров, fps.
exp — мой опыт по реальным прогонам: {стиль: отзыв}, ключи из STYLES. Нет ключа — в этом стиле не запускалось.
  Отзыв — что получилось и что нет, с цифрами (разрешение, время, сколько вариантов годных). После каждого запуска дописывай.
Тексты — по-русски, коротко. Источники — в ~/ai/tools/research/web.md.
"""

# колонки «Опыт» в таблице: ключ → заголовок
STYLES = [('real', 'Реализм'), ('anime', 'Аниме'), ('drawn', 'Рисованное, 2D'),
          ('graphic', 'Графика и текст'), ('sound', 'Звук')]

# листы таблицы: ключ → заголовок, колонки умений [(ключ cap, заголовок)], стили «Опыта» на листе
SHEETS = [
    ('photo', 'Фото', [('t2i', 'Из текста'), ('edit', 'Правка по инструкции'), ('inpaint', 'Инпейнт по маске'),
                       ('ctrl', 'Поза, глубина, канни'), ('ref', 'Референсы'),
                       ('text', 'Текст на картинке'), ('neg', 'Negative'), ('lora', 'LoRA'), ('ru', 'Промпт по-русски')],
     ['real', 'anime', 'drawn', 'graphic']),
    ('video', 'Видео', [('t2v', 'Из текста'), ('i2v', 'Из картинки'), ('flf', 'Первый + последний кадр'), ('ext', 'Продолжение'),
                        ('audio', 'Звук'), ('lips', 'Речь, губы'), ('ref', 'Референсы лица, персонажа'),
                        ('motion', 'Движение или контроль из видео'), ('vedit', 'Правка видео'), ('ru', 'Промпт по-русски'),
                        ('len', 'Длина за прогон')],
     ['real', 'anime', 'drawn', 'graphic', 'sound']),
    ('audio', 'Аудио', [('tts', 'Речь из текста'), ('ru', 'Русский'), ('clone', 'Клон голоса'), ('design', 'Голос по описанию'),
                        ('emo', 'Эмоции, теги'), ('dialog', 'Диалог'), ('vocal', 'Песня с вокалом'), ('inst', 'Инструментал, SFX'),
                        ('v2a', 'Звук к видео'), ('asr', 'Аудио → текст'), ('sr', 'Частота')],
     ['sound']),
    ('3d', '3D', [('t23d', 'Из текста'), ('i23d', 'Из картинки'), ('mv23d', 'Мультиракурс'),
                  ('pbr', 'PBR-текстуры'), ('format', 'Формат (GLB/PLY)'), ('topo', 'Топология / Ремеш'),
                  ('uv', 'UV-развёртка')],
     ['real', 'anime', 'drawn', 'graphic']),
    ('upscale', 'Апскейл', [('scale', 'Масштаб'), ('gen', 'Дорисовывает детали'), ('restore', 'Реставрация (шум, мыло, сжатие)'),
                            ('drawn', 'Аниме и 2D'), ('prompt', 'Промпт')],
     ['real', 'anime', 'drawn', 'graphic']),
    ('tool', 'Утилиты и LLM', [('prompt', 'Управление текстом'), ('use', 'Куда дальше')],
     ['real', 'anime', 'drawn', 'graphic']),
]

R = []


def sheet_of(cat):
    if cat.startswith(('Фото', 'Редактирование фото')):
        return 'photo'
    if cat.startswith('3D'):
        return '3d'
    return {'Видео': 'video', 'Аудио': 'audio', 'Апскейл': 'upscale'}.get(cat.split(':')[0].split(' ')[0], 'tool')


def m(split=(), **kw):
    assert not (split and 'exp' in kw), f"{kw['id']}: exp пиши внутри режима"
    for s in split or [{}]:
        row = {**kw, **{k: v for k, v in s.items() if k != 'add'}, 'base': kw['id'], 'model': kw['name']}
        for k, v in s.get('add', {}).items():
            row[k] = (row[k] + ' ' + v).strip()
        if split:
            row['name'] = f"{kw['name']} · {s['mode']}"
        assert row.get('mode') and 'cap' in row, f"{row['id']}: нет mode или cap"
        row['sheet'] = sheet_of(row['cat'])
        R.append(row)


